-- ========================================================================

-- Audit trail of every scoring rule that fired for a blood test result.

CREATE TABLE blood_test_result_grade_rule (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    blood_test_result_grade_id UUID NOT NULL
        REFERENCES blood_test_result_grade(id) ON DELETE CASCADE,
    rule_id VARCHAR(40) NOT NULL,
    axis VARCHAR(20) NOT NULL DEFAULT ''
        CHECK (axis IN ('classification', 'severity', 'completeness', 'follow-up', '')),
    category VARCHAR(50) NOT NULL DEFAULT '',
    description VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_blood_test_result_grade_rule_grade_id
    ON blood_test_result_grade_rule(blood_test_result_grade_id);

CREATE TRIGGER trigger_blood_test_result_grade_rule_updated_at
    BEFORE UPDATE ON blood_test_result_grade_rule
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE blood_test_result_grade_rule IS
    'Audit trail of every classification / severity / completeness / follow-up rule that fired for this result.';
COMMENT ON COLUMN blood_test_result_grade_rule.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN blood_test_result_grade_rule.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN blood_test_result_grade_rule.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN blood_test_result_grade_rule.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN blood_test_result_grade_rule.blood_test_result_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN blood_test_result_grade_rule.rule_id IS
    'Stable rule identifier (e.g. R-CLASS-CRITICAL-01).';
COMMENT ON COLUMN blood_test_result_grade_rule.axis IS
    'Scoring axis the rule belongs to: classification, severity, completeness, follow-up.';
COMMENT ON COLUMN blood_test_result_grade_rule.category IS
    'Category or finding the rule relates to.';
COMMENT ON COLUMN blood_test_result_grade_rule.description IS
    'Human-readable description of why the rule fired.';

-- ========================================================================
-- END 06_create_table_blood_test_result_grade_rule.sql
-- ========================================================================

-- ========================================================================
-- BEGIN 07_create_table_blood_test_result_grade_flag.sql
-- ========================================================================

-- Safety-critical flags for a blood test result, independent of the axes.

CREATE TABLE blood_test_result_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    blood_test_result_grade_id UUID NOT NULL
        REFERENCES blood_test_result_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'critical-result-alert',
            'incidental-finding',
            'discrepancy-with-request',
            'abnormal-requiring-action',
            'urgent-referral',
            'inadequate-specimen',
            'unexpected-finding',
            'missing-impression',
            'missing-result-value',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_blood_test_result_grade_flag_grade_id
    ON blood_test_result_grade_flag(blood_test_result_grade_id);

CREATE TRIGGER trigger_blood_test_result_grade_flag_updated_at
    BEFORE UPDATE ON blood_test_result_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE blood_test_result_grade_flag IS
    'Safety-critical flags that fire independently of the four axes, with priority and a suggested action for the reporting / requesting team.';
COMMENT ON COLUMN blood_test_result_grade_flag.id IS
    'Primary key UUID, auto-generated.';
COMMENT ON COLUMN blood_test_result_grade_flag.created_at IS
    'Timestamp when this row was created.';
COMMENT ON COLUMN blood_test_result_grade_flag.updated_at IS
    'Timestamp when the record was updated most-recently.';
COMMENT ON COLUMN blood_test_result_grade_flag.deleted_at IS
    'Timestamp when the record was deleted a.k.a. soft-removed.';
COMMENT ON COLUMN blood_test_result_grade_flag.blood_test_result_grade_id IS
    'Foreign key to the parent grade.';
COMMENT ON COLUMN blood_test_result_grade_flag.flag_id IS
    'Stable flag identifier (e.g. F-CRITICAL-RESULT-001).';
COMMENT ON COLUMN blood_test_result_grade_flag.category IS
    'Flag category.';
COMMENT ON COLUMN blood_test_result_grade_flag.priority IS
    'Priority: low, medium, high.';
COMMENT ON COLUMN blood_test_result_grade_flag.description IS
    'Human-readable description of what fired the flag.';
COMMENT ON COLUMN blood_test_result_grade_flag.suggested_action IS
    'Suggested clinical action (e.g. "communicate critical result to requester and document").';

